// Authored serializer support; production methods are generated by the test runner.
#pragma once
// This fixture runs the patched game's real career serializer, not a model of it.
typedef int BOOL;
typedef short SWORD;
#ifndef TRUE
#define TRUE 1
#define FALSE 0
#endif
#ifndef ASSERT
#define ASSERT(expression) do {} while (0)
#endif
struct SControlBinding { int mId; bool mConfigurable; int authoredKey; };
static SControlBinding CONTROL_BINDINGS[] = {{0, true, 17}, {1, false, 23}, {-1, false, 0}};
static int optionWrites = 0;
static SWORD current_version_stamp() { return 7; }
static bool clearSavedGodFlags = true;
extern "C" int PortCeCareerSaving(CCareer*) { return clearSavedGodFlags; }
extern "C" void PortCeBonusFilterSave(CCareer*, void*) {}
extern "C" void PortCeMuseumVisitFilterSave(CCareer*, void*) {} // patch 0279: no visit holds a career in this fixture
char* CCareer::WriteOptions(char* dest) { ++optionWrites; *dest = 42; return dest + 1; }
#undef ASSERT
#define ASSERT(value) Check((value), "career serialization invariant")
#define CE_VERSION 1
#ifdef EDITOR_MUSEUM_COMPOSED
#include "editor-museum-filter.private.inc"
#endif
