#undef CE_VERSION


static void SetFixtureOptions(CCareer& career, int generation) {
    career.musicVolume = 0.125f + generation * 0.03125f;
    career.soundVolume = 0.625f - generation * 0.03125f;
    for (int player = 0; player < 2; ++player) {
        career.invertYAxis[player] = (generation + player) & 1;
        career.invertJetYAxis[player] = (generation + player + 1) & 1;
        career.isGod[player] = (generation + player) & 1;
        career.vibration[player] = (generation + player + 1) & 1;
        career.controllerConfiguration[player] = generation * 3 + player;
    }
    career.screenPosX = generation * 7 - 4;
    career.screenPosY = generation * 5 + 3;
}

static bool SameFixtureOptions(const CCareer& left, const CCareer& right) {
    return left.musicVolume == right.musicVolume && left.soundVolume == right.soundVolume &&
        std::memcmp(left.invertYAxis, right.invertYAxis, sizeof(left.invertYAxis)) == 0 &&
        std::memcmp(left.invertJetYAxis, right.invertJetYAxis, sizeof(left.invertJetYAxis)) == 0 &&
        std::memcmp(left.isGod, right.isGod, sizeof(left.isGod)) == 0 &&
        std::memcmp(left.vibration, right.vibration, sizeof(left.vibration)) == 0 &&
        std::memcmp(left.controllerConfiguration, right.controllerConfiguration,
                    sizeof(left.controllerConfiguration)) == 0 &&
        left.screenPosX == right.screenPosX && left.screenPosY == right.screenPosY;
}

static bool SameFixtureProgress(const CCareer& left, const CCareer& right) {
    return std::memcmp(left.progress, right.progress, sizeof(left.progress)) == 0 &&
        left.mCareerInProgress == right.mCareerInProgress;
}

static void ProbeSavedCareer(const CCareer& progress, const CCareer& options, bool fenced) {
    for (int mark = 0; mark < 2; ++mark) {
        std::vector<char> bytes(4096, 0x5a);
        const CCareer live = CAREER;
        const int writes = optionWrites;
        if (mark) CAREER.SaveAndMarkInProgress(bytes.data() + 32);
        else CAREER.Save(bytes.data() + 32);
        CCareer expectedLive = live;
        if (mark) expectedLive.mCareerInProgress = TRUE;
        Check(std::memcmp(&CAREER, &expectedLive, sizeof(expectedLive)) == 0,
              "serialization retains live data and the mark-in-progress behavior");
        CCareer saved;
        std::memcpy(&saved, bytes.data() + 32 + sizeof(SWORD), sizeof(saved));
        CCareer expectedProgress = progress;
        if (mark && !fenced) expectedProgress.mCareerInProgress = TRUE;
        CCareer expectedOptions = options;
        if (clearSavedGodFlags) {
            for (int player = 0; player < 2; ++player) expectedOptions.isGod[player] = FALSE;
        }
        Check(std::memcmp(saved.progress, expectedProgress.progress, sizeof(saved.progress)) == 0,
              fenced ? "fenced payload contains the entry scores" : "ordinary payload contains current scores");
        Check(saved.mCareerInProgress == expectedProgress.mCareerInProgress,
              fenced ? "fenced payload contains the entry progress marker" : "ordinary payload contains the current progress marker");
        Check(SameFixtureOptions(saved, expectedOptions),
              "actual save payload contains current options and the save policy");
        Check(optionWrites == writes + 1, "actual serializer retains the controller option tail");
        for (int i = 0; i < 32; ++i)
            Check(bytes[i] == 0x5a && bytes[bytes.size() - 1 - i] == 0x5a,
                  "serialization respects the output buffer bounds");
    }
}

static void CheckFilterNullArguments() {
    std::vector<unsigned char> bytes(sizeof(CCareer), 0x67);
    const CCareer live = CAREER;
    PortCeEditorFilterSave(nullptr, bytes.data());
    PortCeEditorFilterSave(&CAREER, nullptr);
    PortCeEditorFilterSave(nullptr, nullptr);
    for (unsigned char byte : bytes) Check(byte == 0x67, "null source leaves the destination alone");
    Check(std::memcmp(&CAREER, &live, sizeof(live)) == 0,
          "invalid filter arguments preserve the live career");
}
